public class SearchIndex
{
    private readonly InvertedIndex _index = new();

    public void Index(Message message)
    {
        var words = message.Text.ToLowerInvariant().Split(' ', StringSplitOptions.RemoveEmptyEntries);
        foreach (var word in words)
            _index.Add(word, message.Id);
    }

    public IEnumerable<Message> Search(string query, Guid? channelId = null)
    {
        var words = query.ToLowerInvariant().Split(' ');
        var results = words.SelectMany(w => _index.Lookup(w)).Distinct();
        return results.Select(id => _messages[id])
            .Where(m => channelId == null || m.ChannelId == channelId.Value)
            .OrderByDescending(m => m.SentAt);
    }
}

public class NotificationPreferences
{
    public Guid UserId { get; set; }
    public Dictionary<Guid, bool> ChannelMute { get; } = new();
    public bool AllMuted { get; set; }

    public bool ShouldNotify(Guid channelId)
    {
        if (AllMuted) return false;
        return !ChannelMute.GetValueOrDefault(channelId);
    }
}
